import{$ as e,A as t,B as n,V as r}from"./chunks/framework.Civ1omIV.js";var i=JSON.parse(`{"title":"Supported proxy protocols in Clash for iPhone and iPad","description":"The complete list of 21 outbound protocol families supported by Clash, including Shadowsocks, VMess, VLESS, Trojan, Hysteria2, TUIC, WireGuard and OpenVPN.","frontmatter":{"title":"Supported proxy protocols in Clash for iPhone and iPad","description":"The complete list of 21 outbound protocol families supported by Clash, including Shadowsocks, VMess, VLESS, Trojan, Hysteria2, TUIC, WireGuard and OpenVPN.","head":[["meta",{"name":"keywords","content":"Clash supported protocols,Clash iOS Shadowsocks,VMess,VLESS,Trojan,Hysteria2,TUIC,WireGuard,OpenVPN,AnyTLS,Snell"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"FAQPage\\",\\"mainEntity\\":[{\\"@type\\":\\"Question\\",\\"name\\":\\"Which proxy protocols does Clash support?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Clash supports 21 outbound protocol families: HTTP, SOCKS, Shadowsocks, ShadowsocksR, Snell, VMess, VLESS, Trojan, AnyTLS, Mieru, Sudoku, Hysteria, Hysteria2, TUIC, ShadowQUIC, WireGuard, Tailscale, SSH, MASQUE, TrustTunnel and OpenVPN.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I use ss:// and other share links with Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Convert standalone share links or Base64 node lists to mihomo YAML, or enter the server, port, credentials and protocol parameters in the node editor. The Profile importer accepts HTTPS subscription URLs and complete mihomo YAML.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"How do I move a configuration from another app?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Prefer a provider-supplied mihomo YAML subscription. Nodes from sing-box, Surge, or Quantumult X can also be recreated in Clash from their protocol parameters.\\"}},{\\"@type\\":\\"Question\\",\\"name\\":\\"What do I need to start using Clash?\\",\\"acceptedAnswer\\":{\\"@type\\":\\"Answer\\",\\"text\\":\\"Bring a server configuration or HTTPS subscription that you choose and trust, then import it into Clash.\\"}}]}"]]},"headers":[],"relativePath":"guide/protocols.md","filePath":"guide/protocols.md","lastUpdated":0}`),a={name:`guide/protocols.md`};function o(t,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[r(`<h1 id="supported-proxy-protocols-in-clash" tabindex="-1">Supported proxy protocols in Clash <a class="header-anchor" href="#supported-proxy-protocols-in-clash" aria-label="Permalink to “Supported proxy protocols in Clash”">​</a></h1><p>Clash for iPhone and iPad supports <strong>21 outbound protocol families</strong>. Configure them through mihomo YAML, an HTTPS subscription that returns mihomo YAML, or the node editor.</p><h2 id="complete-protocol-list" tabindex="-1">Complete protocol list <a class="header-anchor" href="#complete-protocol-list" aria-label="Permalink to “Complete protocol list”">​</a></h2><table tabindex="0"><thead><tr><th>Protocol</th><th>Available import paths</th></tr></thead><tbody><tr><td>HTTP</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>SOCKS</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>Shadowsocks</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>ShadowsocksR</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>Snell</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>VMess</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>VLESS</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>Trojan</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>AnyTLS</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>Mieru</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>Sudoku</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>Hysteria</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>Hysteria2</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>TUIC</td><td>mihomo YAML · compatible subscription · manual node</td></tr><tr><td>ShadowQUIC</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>WireGuard</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>Tailscale</td><td>mihomo YAML · manual node</td></tr><tr><td>SSH</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>MASQUE</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>TrustTunnel</td><td>mihomo YAML · subscription · manual node</td></tr><tr><td>OpenVPN</td><td>mihomo YAML · subscription · manual node</td></tr></tbody></table><h2 id="configuration-paths" tabindex="-1">Configuration paths <a class="header-anchor" href="#configuration-paths" aria-label="Permalink to “Configuration paths”">​</a></h2><p>The current iOS client accepts these Profile sources:</p><ul><li>an HTTPS subscription URL whose response is valid mihomo YAML;</li><li>a <code>.yaml</code> or <code>.yml</code> configuration file;</li><li>complete mihomo YAML from the clipboard;</li><li>a QR code containing an HTTPS subscription URL.</li></ul><p>For standalone node links such as <code>ss://</code>, <code>ssr://</code>, and <code>vmess://</code>, or a Base64 node list, convert the source to mihomo YAML or recreate the node from its server, port, credentials, and protocol parameters in the node editor.</p><h2 id="move-nodes-from-another-app" tabindex="-1">Move nodes from another app <a class="header-anchor" href="#move-nodes-from-another-app" aria-label="Permalink to “Move nodes from another app”">​</a></h2><p>Clash uses mihomo YAML as its configuration format. When moving from sing-box JSON, a Surge profile, or Quantumult X, prefer a mihomo subscription or recreate the node in Clash from its protocol parameters.</p><p>For recommended migration paths by app, read the <a href="/clash.md/guide/compatibility">compatibility guide</a>.</p><h2 id="configuration-essentials" tabindex="-1">Configuration essentials <a class="header-anchor" href="#configuration-essentials" aria-label="Permalink to “Configuration essentials”">​</a></h2><ul><li>Use a server, credentials, and protocol parameters you choose and trust.</li><li>Match TLS, transport, obfuscation, UDP, and authentication options to the server.</li><li>Choose a transport and UDP mode supported by the protocol.</li><li>Run latency and live connection tests after saving.</li></ul><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to “Frequently asked questions”">​</a></h2><h3 id="does-clash-support-shadowsocksr" tabindex="-1">Does Clash support ShadowsocksR? <a class="header-anchor" href="#does-clash-support-shadowsocksr" aria-label="Permalink to “Does Clash support ShadowsocksR?”">​</a></h3><p>Yes. ShadowsocksR is available through mihomo YAML, a compatible subscription that returns mihomo YAML, or by entering the parameters from an <code>ssr://</code> link in the node editor.</p><h3 id="does-clash-support-wireguard-openvpn-and-tailscale" tabindex="-1">Does Clash support WireGuard, OpenVPN and Tailscale? <a class="header-anchor" href="#does-clash-support-wireguard-openvpn-and-tailscale" aria-label="Permalink to “Does Clash support WireGuard, OpenVPN and Tailscale?”">​</a></h3><p>Yes. They are available as outbound types. Their credentials, addresses, routes and other required fields must be configured correctly.</p><h3 id="does-clash-support-hysteria2-tuic-and-anytls" tabindex="-1">Does Clash support Hysteria2, TUIC and AnyTLS? <a class="header-anchor" href="#does-clash-support-hysteria2-tuic-and-anytls" aria-label="Permalink to “Does Clash support Hysteria2, TUIC and AnyTLS?”">​</a></h3><p>Yes. All three are supported through mihomo YAML, compatible subscriptions that return mihomo YAML, or manual node entry.</p><h3 id="does-clash-support-snell-for-surge-servers" tabindex="-1">Does Clash support Snell for Surge servers? <a class="header-anchor" href="#does-clash-support-snell-for-surge-servers" aria-label="Permalink to “Does Clash support Snell for Surge servers?”">​</a></h3><p>Yes. Configure a compatible Snell server in Clash, then recreate its policy groups and rules in mihomo YAML.</p><h3 id="are-these-protocols-available-on-both-iphone-and-ipad" tabindex="-1">Are these protocols available on both iPhone and iPad? <a class="header-anchor" href="#are-these-protocols-available-on-both-iphone-and-ipad" aria-label="Permalink to “Are these protocols available on both iPhone and iPad?”">​</a></h3><p>Yes. Clash is a universal iOS/iPadOS app and uses the same Hako data plane on both device families.</p>`,24)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};